package org.apache.commons.math3.optimization.general;

import org.apache.commons.math3.linear.DiagonalMatrix;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.optimization.PointVectorValuePair;
import org.apache.commons.math3.util.FastMath;
import org.junit.Assert;
import org.junit.Test;

import java.lang.reflect.Method;

public class AgentBRT_Math_13_raw_diff_Test {

    @Test
    public void testReproduceBug() throws Exception {
        // Create a diagonal matrix with positive entries
        double[] diagonalEntries = {4.0, 9.0, 16.0};
        DiagonalMatrix matrix = new DiagonalMatrix(diagonalEntries);

        // Expected square root matrix
        double[] expectedSqrtEntries = {2.0, 3.0, 4.0};
        DiagonalMatrix expectedSqrtMatrix = new DiagonalMatrix(expectedSqrtEntries);

        // Create a subclass to access the private method
        AbstractLeastSquaresOptimizer optimizer = new AbstractLeastSquaresOptimizer() {
            @Override
            protected PointVectorValuePair doOptimize() {
                return null; // Not needed for this test
            }
        };

        // Use reflection to access the private squareRoot method
        Method squareRootMethod = AbstractLeastSquaresOptimizer.class.getDeclaredMethod("squareRoot", RealMatrix.class);
        squareRootMethod.setAccessible(true);
        RealMatrix result = (RealMatrix) squareRootMethod.invoke(optimizer, matrix);

        // Assert that the result is as expected
        for (int i = 0; i < diagonalEntries.length; i++) {
            Assert.assertEquals(expectedSqrtMatrix.getEntry(i, i), result.getEntry(i, i), 1e-10);
        }
    }
}

